	job := zkcircuit.Job{ID: f.id, Circuit: f.name, Version: f.version, Kind: f.kind, Attempt: f.attempt, CompiledHash: f.hash}
	stored, err := store.SubmitJob(job)
	if err != nil {
		return reportStoreError(err)
