1	package zkcircuit
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"strings"
11		"testing"
12	)
13	
14	// These tests pin the read-time contract for a circuit record already
15	// committed in data.json: name, version, constraints, public_inputs,
16	// private_inputs, frozen and description must each be present exactly once
17	// with the exact JSON type the writer emits. A missing key, null, wrong type
18	// or repeated key (including a key spelled through a JSON escape, or repeated
19	// with the same value) is data corruption: the whole directory fails to read
20	// rather than silently filling 0/false/"".
21	
22	// seedClosedStore creates a store, optionally seeds a complete circuit
23	// (definition imported, then frozen) and closes it, returning its directory.
24	func seedClosedStore(t *testing.T, frozen bool) string {
25		t.Helper()
26		dir := filepath.Join(t.TempDir(), "bench")
27		s, err := Open(dir)
28		if err != nil {
29			t.Fatal(err)
30		}
31		const goodDef = `{"modulus":"7","constraints":[
32			{"a":[{"wire":1,"coeff":"1"}],"b":[{"wire":2,"coeff":"1"}],"c":[{"wire":0,"coeff":"6"}]}]}`
33		seedDraftWithDef(t, s, "mul", 1, 1, 1, goodDef)
34		if frozen {
35			if _, err := s.FreezeCircuit("mul", 1); err != nil {
36				t.Fatal(err)
37			}
38			if _, err := s.RecordSetup("mul", 1); err != nil {
39				t.Fatal(err)
40			}
41			if _, err := s.CompileCircuit("mul", 1); err != nil {
42				t.Fatal(err)
43			}
44		}
45		if err := s.Close(); err != nil {
46			t.Fatal(err)
47		}
48		return dir
49	}
50	
51	// setCircuitField replaces one top-level field of the first circuit record.
52	func setCircuitField(field string, value any) func(map[string]any) {
53		return func(env map[string]any) {
54			readFirstCircuit(env)[field] = value
55		}
56	}
57	
58	func deleteCircuitField(field string) func(map[string]any) {
59		return func(env map[string]any) {
60			delete(readFirstCircuit(env), field)
61		}
62	}
63	
64	func readFirstCircuit(env map[string]any) map[string]any {
65		return env["circuits"].([]any)[0].(map[string]any)
66	}
67	
68	func requireCorruptAndUntouched(t *testing.T, dir string, bad []byte, wantField string) {
69		t.Helper()
70		s, err := Open(dir)
71		if err == nil {
72			s.Close()
73			t.Fatalf("damaged circuit record was accepted")
74		}
75		var se StoreError
76		if !errors.As(err, &se) || se.Kind != ErrDataCorrupt.Kind {
77			t.Fatalf("want ErrDataCorrupt, got %v", err)
78		}
79		if wantField != "" && !strings.Contains(err.Error(), wantField) {
80			t.Fatalf("error does not name the damaged field %q: %v", wantField, err)
81		}
82		left, rerr := os.ReadFile(filepath.Join(dir, dirDataFile))
83		if rerr != nil {
84			t.Fatal(rerr)
85		}
86		if string(left) != string(bad) {
87			t.Fatalf("refused read modified data.json\nwant: %q\n got: %q", bad, left)
88		}
89		if s2, err := Open(dir); err == nil {
90			s2.Close()
91			t.Fatalf("reopen accepted the damage")
92		} else if !errors.Is(err, ErrDataCorrupt) {
93			t.Fatalf("reopen: want ErrDataCorrupt, got %v", err)
94		}
95	}
96	
97	// TestCorruptCircuitRecordFieldsRefused damages each required field of a
98	// committed circuit record in turn; whether the version is a draft or frozen
99	// (trusted setup + compiled artifact), the directory must be unreadable.
100	func TestCorruptCircuitRecordFieldsRefused(t *testing.T) {
101		damage := []struct {
102			name      string
103			mutate    func(map[string]any)
104			wantField string
105		}{
106			{"missing name", deleteCircuitField("name"), `"name"`},
107			{"null name", setCircuitField("name", nil), `"name"`},
108			{"numeric name", setCircuitField("name", 7), `"name"`},
109			{"missing version", deleteCircuitField("version"), `"version"`},
110			{"null version", setCircuitField("version", nil), `"version"`},
111			{"string version", setCircuitField("version", "1"), `"version"`},
112			{"float version", setCircuitField("version", 1.5), `"version"`},
113			{"missing constraints", deleteCircuitField("constraints"), `"constraints"`},
114			{"null constraints", setCircuitField("constraints", nil), `"constraints"`},
115			{"string constraints", setCircuitField("constraints", "1"), `"constraints"`},
116			{"missing public_inputs", deleteCircuitField("public_inputs"), `"public_inputs"`},
117			{"null public_inputs", setCircuitField("public_inputs", nil), `"public_inputs"`},
118			{"float public_inputs", setCircuitField("public_inputs", 0.5), `"public_inputs"`},
119			{"string public_inputs", setCircuitField("public_inputs", "0"), `"public_inputs"`},
120			{"missing private_inputs", deleteCircuitField("private_inputs"), `"private_inputs"`},
121			{"null private_inputs", setCircuitField("private_inputs", nil), `"private_inputs"`},
122			{"bool private_inputs", setCircuitField("private_inputs", true), `"private_inputs"`},
123			// The headline damage: a frozen record whose frozen flag is deleted or
124			// null must not come back as an editable draft.
125			{"missing frozen", deleteCircuitField("frozen"), `"frozen"`},
126			{"null frozen", setCircuitField("frozen", nil), `"frozen"`},
127			{"string frozen", setCircuitField("frozen", "true"), `"frozen"`},
128			{"numeric frozen", setCircuitField("frozen", 1), `"frozen"`},
129			{"missing description", deleteCircuitField("description"), `"description"`},
130			{"null description", setCircuitField("description", nil), `"description"`},
131			{"numeric description", setCircuitField("description", 1), `"description"`},
132		}
133	
134		for _, frozen := range []bool{false, true} {
135			state := "draft"
136			if frozen {
137				state = "frozen-setup-compiled"
138			}
139			t.Run(state, func(t *testing.T) {
140				for _, tc := range damage {
141					t.Run(tc.name, func(t *testing.T) {
142						dir := seedClosedStore(t, frozen)
143						env := readGenericEnv(t, dir)
144						tc.mutate(env)
145						bad := writeGenericEnv(t, dir, env)
146						requireCorruptAndUntouched(t, dir, bad, tc.wantField)
147					})
148				}
149			})
150		}
151	}
