153	// compactCircuitRecord extracts the first circuit record from a raw envelope
154	// and returns it compacted, plus a function to re-embed a replacement.
155	func compactCircuitRecord(t *testing.T, raw []byte) (record []byte, embed func([]byte) []byte) {
156		t.Helper()
157		var wire struct {
158			Circuits []json.RawMessage `json:"circuits"`
159		}
160		if err := json.Unmarshal(raw, &wire); err != nil {
161			t.Fatal(err)
162		}
163		orig := []byte(wire.Circuits[0])
164		var compact bytes.Buffer
165		if err := json.Compact(&compact, orig); err != nil {
166			t.Fatal(err)
167		}
168		return compact.Bytes(), func(rep []byte) []byte {
169			return bytes.Replace(raw, orig, rep, 1)
170		}
171	}
172	
173	// appendRecordField returns a compact record JSON copy with an extra raw
174	// member inserted before the closing brace: `...,"field":value`.
175	func appendRecordField(t *testing.T, record []byte, member string) []byte {
176		t.Helper()
177		if len(record) == 0 || record[len(record)-1] != '}' {
178			t.Fatalf("record does not end with }: %s", record)
179		}
180		out := make([]byte, 0, len(record)+len(member)+1)
181		out = append(out, record[:len(record)-1]...)
182		out = append(out, ',')
183		out = append(out, member...)
184		out = append(out, '}')
185		// Must stay parseable JSON.
186		var probe map[string]json.RawMessage
187		if err := json.Unmarshal(out, &probe); err != nil {
188			t.Fatalf("crafted record is not valid JSON: %v (%s)", err, out)
189		}
190		return out
191	}
192	
193	// TestDuplicateCircuitFieldsRefused: every field appearing twice is
194	// corruption — with a differing value, with the same value, and when one
195	// occurrence spells the key through a JSON escape (encoding/json decodes the
196	// escaped key to the same string and would otherwise keep one value).
197	func TestDuplicateCircuitFieldsRefused(t *testing.T) {
198		fields := []string{
199			"name", "version", "constraints", "public_inputs",
200			"private_inputs", "frozen", "description",
201		}
202		values := map[string]string{
203			"name": `"other"`, "version": `2`, "constraints": `9`,
204			"public_inputs": `4`, "private_inputs": `5`,
205			"description": `"changed"`,
206		}
207		// escapedKey spells one byte of the key as \u00XX: JSON decoding makes it
208		// the identical member name, so it is still a duplicate.
209		escapedKey := func(key string) string {
210			return fmt.Sprintf("\"\\u%04x%s\"", key[0], key[1:])
211		}
212	
213		for _, frozen := range []bool{false, true} {
214			// The duplicated value differs from the stored one: flip frozen.
215			values["frozen"] = `true`
216			if frozen {
217				values["frozen"] = `false`
218			}
219			state := "draft"
220			if frozen {
221				state = "frozen"
222			}
223			t.Run(state, func(t *testing.T) {
224				for _, field := range fields {
225					t.Run(field+"/different value", func(t *testing.T) {
226						dir := seedClosedStore(t, frozen)
227						raw, err := os.ReadFile(filepath.Join(dir, dirDataFile))
228						if err != nil {
229							t.Fatal(err)
230						}
231						rec, embed := compactCircuitRecord(t, raw)
232						badRec := appendRecordField(t, rec, fmt.Sprintf("%q:%s", field, values[field]))
233						bad := embed(badRec)
234						if err := os.WriteFile(filepath.Join(dir, dirDataFile), bad, 0o644); err != nil {
235							t.Fatal(err)
236						}
237						requireCorruptAndUntouched(t, dir, bad, field)
238					})
239					t.Run(field+"/same value", func(t *testing.T) {
240						dir := seedClosedStore(t, frozen)
241						raw, err := os.ReadFile(filepath.Join(dir, dirDataFile))
242						if err != nil {
243							t.Fatal(err)
244						}
245						rec, embed := compactCircuitRecord(t, raw)
246						var probe map[string]json.RawMessage
247						if err := json.Unmarshal(rec, &probe); err != nil {
248							t.Fatal(err)
249						}
250						badRec := appendRecordField(t, rec,
251							fmt.Sprintf("%q:%s", field, string(probe[field])))
252						bad := embed(badRec)
253						if err := os.WriteFile(filepath.Join(dir, dirDataFile), bad, 0o644); err != nil {
254							t.Fatal(err)
255						}
256						requireCorruptAndUntouched(t, dir, bad, field)
257					})
258					t.Run(field+"/escaped key", func(t *testing.T) {
259						dir := seedClosedStore(t, frozen)
260						raw, err := os.ReadFile(filepath.Join(dir, dirDataFile))
261						if err != nil {
262							t.Fatal(err)
263						}
264						rec, embed := compactCircuitRecord(t, raw)
265						var probe map[string]json.RawMessage
266						if err := json.Unmarshal(rec, &probe); err != nil {
267							t.Fatal(err)
268						}
269						// The second occurrence escapes one byte of the key; it is
270						// the same JSON field name.
271						badRec := appendRecordField(t, rec,
272							escapedKey(field)+":"+string(probe[field]))
273						bad := embed(badRec)
274						if err := os.WriteFile(filepath.Join(dir, dirDataFile), bad, 0o644); err != nil {
275							t.Fatal(err)
276						}
277						requireCorruptAndUntouched(t, dir, bad, field)
278					})
279				}
280			})
281		}
282	}
283	
284	// TestUnknownCircuitFieldRefused: a committed record may only carry the
285	// fields the writer emits; an unknown member is refused instead of being
286	// silently ignored (a typo next to a real required field must not pass).
287	func TestUnknownCircuitFieldRefused(t *testing.T) {
288		for _, field := range []string{`"note":"x"`, `"frzoen":true`} {
289			t.Run(field, func(t *testing.T) {
290				dir := seedClosedStore(t, true)
291				raw, err := os.ReadFile(filepath.Join(dir, dirDataFile))
292				if err != nil {
293					t.Fatal(err)
294				}
295				rec, embed := compactCircuitRecord(t, raw)
296				badRec := appendRecordField(t, rec, field)
297				bad := embed(badRec)
298				if err := os.WriteFile(filepath.Join(dir, dirDataFile), bad, 0o644); err != nil {
299					t.Fatal(err)
300				}
301				requireCorruptAndUntouched(t, dir, bad, "unknown field")
302			})
