	"path/filepath"

	"github.com/asdhoaiqqq/zkcircuit-workbench/zkcircuit"
)

func main() {
	dir, _ := os.MkdirTemp("", "zk")
	defer os.RemoveAll(dir)
	s, _ := zkcircuit.Open(dir)
	def, _ := os.CreateTemp(dir, "def*.json")
	os.WriteFile(def.Name(), []byte(`{"modulus":"7","constraints":[{"a":[{"wire":1,"coeff":"1"}],"b":[{"wire":2,"coeff":"1"}],"c":[{"wire":0,"coeff":"6"}]}]}`), 0o644)
	s.CreateCircuit(zkcircuit.Circuit{Name: "c", Version: 1, Constraints: 1, PublicInputs: 1, PrivateInputs: 1})
	s.ImportConstraints("c", 1, def.Name())
	s.FreezeCircuit("c", 1)
	s.RecordSetup("c", 1)
	a, _ := s.CompileCircuit("c", 1)
	s.SubmitJob(zkcircuit.Job{ID: "j1", Circuit: "c", Version: 1, Kind: "prove", Attempt: 1, CompiledHash: a.Hash})
	s.Close()

	raw, _ := os.ReadFile(filepath.Join(dir, "data.json"))
	var env struct {
		Jobs []map[string]any `json:"jobs"`
	}
	json.Unmarshal(raw, &env)
	jb, _ := json.Marshal(env.Jobs[0])
	// duplicate compiled_hash with the 'c' escaped as �
	dupJob := string(jb[:len(jb)-1]) + fmt.Sprintf(`,\"compiled_hash\":%q}`, a.Hash)
	bad := []byte(string(raw))
	bad = appendJSONReplace(bad, jb, []byte(dupJob))
	os.WriteFile(filepath.Join(dir, "data.json"), bad, 0o644)
	_, err := zkcircuit.Open(dir)
	fmt.Println(err)
}

func appendJSONReplace(s, old, new []byte) []byte {
	return []byte(replaceOnce(string(s), string(old), string(new)))
}
func replaceOnce(s, old, new string) string {
	for i := 0; i+len(old) <= len(s); i++ {
		if s[i:i+len(old)] == old {
			return s[:i] + new + s[i+len(old):]
		}
	}
	return s
}
